<template>
	<view class="container">
		<u-loading-page :loading="true" v-if="load" fontSize="28rpx" />
		<block v-else>
		<image :src="share_path"  class="share-img" mode="aspectFill" v-if="share_path!=''"></image>
		<button class="share-btn" @click="saveImg">保存图片</button>
		</block>
	</view>
</template>

<script>
	import downloadImg from '@/components/downloadImg.js'
	var _this;
	export default {
		data() {
			return {
				id: 0,
				share_path:''
			}
		},
		onLoad(e) {
			_this = this;
			if (e.id) {
				_this.id = e.id
			} else {
				this.$u.toast('提交参数有误')
				setTimeout(() => {
					uni.navigateBack()
				}, 2000)
				return;
			}
			_this.goods_fx()
		},
		methods: {
			//获取商品分享海报
			async goods_fx() {
				const params = {
					id: _this.id,
				}
				const data = await _this.$post('port/goods_fx',params)
				if(data.code==200){
					_this.share_path = data.result.share_path
				}else{
					uni.$u.toast(data.msg)
					setTimeout(()=>{
						uni.navigateBack({})
					},2000)
				}
				if (_this.load) {
					_this.load = false
				}
			},
			saveImg(){
				// #ifdef H5
				uni.$u.toast('请长按二维码保存')
				return
				// #endif
				downloadImg(this.share_path)
			}
		}
	}
</script>

<style lang="scss" scoped>
	.container {
		height: 100%;
		overflow: hidden;
		position: relative;
		.share-img{
			width: 100%;
			height: 100%;
		}
		.share-btn{
			background: $bg-btn;
			color: #fff;
			width: 50%;
			border-radius: 80rpx;
			font-size: 28rpx;
			position: absolute;
			left: 25%;
			bottom: 100rpx;
		}
	}
</style>
